export const serviceWorker = "const CACHE = 'chatlk-shell-v3';\nconst PRECACHE_ASSETS = [\n  '/',\n  '/style.css',\n  '/app.js',\n  '/manifest.json',\n  '/offline.html',\n  '/favicon-32x32.png',\n  '/icon-192.png',\n  '/icon-192.svg'\n];\n\nself.addEventListener('install', event => {\n  event.waitUntil(\n    caches.open(CACHE)\n      .then(cache => cache.addAll(PRECACHE_ASSETS))\n      .then(() => self.skipWaiting())\n  );\n});\n\nself.addEventListener('activate', event => {\n  event.waitUntil(\n    caches.keys().then(keys =>\n      Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k)))\n    ).then(() => clients.claim())\n  );\n});\n\nself.addEventListener('fetch', event => {\n  const req = event.request;\n  if (req.method !== 'GET') return;\n\n  // For HTML page navigation: network-first with cached /offline.html fallback\n  if (req.mode === 'navigate') {\n    event.respondWith(\n      fetch(req).catch(() =>\n        caches.match(req).then(cached => cached || caches.match('/offline.html'))\n      )\n    );\n    return;\n  }\n\n  // For static assets: cache-first with network fallback\n  event.respondWith(\n    caches.match(req).then(cached => {\n      if (cached) return cached;\n      return fetch(req).then(response => {\n        if (response && response.ok && req.url.startsWith(self.location.origin) && !req.url.includes('/api/') && !req.url.includes('/ws')) {\n          const clone = response.clone();\n          caches.open(CACHE).then(cache => cache.put(req, clone));\n        }\n        return response;\n      });\n    })\n  );\n});\n\nself.addEventListener('push', event => {\n  const data = event.data ? event.data.json() : {};\n  event.waitUntil(\n    self.registration.showNotification(data.title || 'ChatLK', {\n      body: data.body || 'New message',\n      icon: data.icon || '/icon-192.png',\n      badge: '/favicon-32x32.png',\n      data: data.data || {}\n    })\n  );\n});\n\nself.addEventListener('notificationclick', event => {\n  event.notification.close();\n  const url = event.notification.data?.chatId ? '/?chat=' + event.notification.data.chatId : '/';\n  event.waitUntil(\n    clients.matchAll({ type: 'window', includeUncontrolled: true }).then(windowClients => {\n      for (const client of windowClients) {\n        if (client.url.includes(url) && 'focus' in client) return client.focus();\n      }\n      if (clients.openWindow) return clients.openWindow(url);\n    })\n  );\n});\n";
