export const offlineHtml = "<!doctype html>\n<html lang=\"si\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#0D6B60\">\n  <meta name=\"color-scheme\" content=\"light dark\">\n  <title>Offline — ChatLK</title>\n  <link rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"/favicon-32x32.png\">\n  <link rel=\"icon\" href=\"/favicon.ico\">\n  <style>\n    :root {\n      --bg: #e8f1ed;\n      --card-bg: #ffffff;\n      --text: #081014;\n      --text-muted: #536471;\n      --forest: #0D6B60;\n      --forest-dark: #08443D;\n      --mint: #25D366;\n      --line: rgba(13, 107, 96, 0.15);\n    }\n    @media (prefers-color-scheme: dark) {\n      :root {\n        --bg: #081014;\n        --card-bg: #0F1C18;\n        --text: #F7F9F9;\n        --text-muted: #8B98A5;\n        --line: rgba(255, 255, 255, 0.1);\n      }\n    }\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body {\n      font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"Helvetica Neue\", sans-serif;\n      background: var(--bg);\n      color: var(--text);\n      min-height: 100vh;\n      display: grid;\n      place-items: center;\n      padding: 24px;\n      text-align: center;\n    }\n    .offline-card {\n      background: var(--card-bg);\n      border: 1px solid var(--line);\n      border-radius: 24px;\n      padding: 40px 28px;\n      max-width: 460px;\n      width: 100%;\n      box-shadow: 0 16px 36px rgba(0, 0, 0, 0.08);\n      animation: fadeIn 0.4s ease-out;\n    }\n    @keyframes fadeIn {\n      from { opacity: 0; transform: translateY(12px); }\n      to { opacity: 1; transform: translateY(0); }\n    }\n    .brand-emblem {\n      width: 80px;\n      height: 80px;\n      margin: 0 auto 20px;\n      border-radius: 20px;\n      background: linear-gradient(135deg, #0D6B60 0%, #062C27 100%);\n      display: grid;\n      place-items: center;\n      box-shadow: 0 10px 24px rgba(13, 107, 96, 0.25);\n    }\n    .brand-emblem img {\n      width: 54px;\n      height: 54px;\n    }\n    .badge-offline {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      padding: 4px 12px;\n      background: rgba(239, 68, 68, 0.12);\n      color: #ef4444;\n      border-radius: 999px;\n      font-size: 0.78rem;\n      font-weight: 700;\n      letter-spacing: 0.05em;\n      text-transform: uppercase;\n      margin-bottom: 14px;\n    }\n    .badge-dot {\n      width: 7px;\n      height: 7px;\n      border-radius: 50%;\n      background: #ef4444;\n    }\n    h1 {\n      font-size: 1.45rem;\n      font-weight: 800;\n      margin-bottom: 14px;\n      letter-spacing: -0.02em;\n    }\n    .message-si {\n      font-size: 1rem;\n      line-height: 1.5;\n      margin-bottom: 10px;\n      font-weight: 500;\n    }\n    .message-ta {\n      font-size: 0.88rem;\n      color: var(--text-muted);\n      line-height: 1.5;\n      margin-bottom: 8px;\n    }\n    .message-en {\n      font-size: 0.88rem;\n      color: var(--text-muted);\n      line-height: 1.5;\n      margin-bottom: 24px;\n    }\n    .btn-retry {\n      width: 100%;\n      min-height: 48px;\n      background: var(--forest);\n      color: #ffffff;\n      border: none;\n      border-radius: 14px;\n      font-size: 1rem;\n      font-weight: 700;\n      cursor: pointer;\n      transition: all 0.2s ease;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 8px;\n      box-shadow: 0 8px 18px rgba(13, 107, 96, 0.22);\n    }\n    .btn-retry:hover {\n      background: var(--forest-dark);\n      transform: translateY(-1px);\n    }\n    .online-indicator {\n      margin-top: 18px;\n      font-size: 0.8rem;\n      color: var(--text-muted);\n    }\n  </style>\n</head>\n<body>\n  <div class=\"offline-card\">\n    <div class=\"brand-emblem\">\n      <img src=\"/icon-192.png\" alt=\"ChatLK Logo\" onerror=\"this.src='/icon-192.svg'\">\n    </div>\n    <div class=\"badge-offline\">\n      <span class=\"badge-dot\"></span> Offline\n    </div>\n    <h1>සම්බන්ධතාවය බිඳ වැටී ඇත</h1>\n    <p class=\"message-si\">ඔබ දැනට අන්තර්ජාල සම්බන්ධතාවයෙන් බැහැරව (Offline) සිටී. කරුණාකර ඔබගේ Wi-Fi හෝ Mobile Data සබඳතාව පරීක්ෂා කරන්න.</p>\n    <p class=\"message-ta\">நீங்கள் தற்போது ஆஃப்லைனில் உள்ளீர்கள். தயவுசெய்து உங்கள் இணைய இணைப்பை சரிபார்க்கவும்.</p>\n    <p class=\"message-en\">You're currently offline. Please check your internet connection.</p>\n    <button class=\"btn-retry\" type=\"button\" onclick=\"window.location.reload()\">\n      <span>නැවත සම්බන්ධ වන්න / Retry</span>\n      <span>↻</span>\n    </button>\n    <p class=\"online-indicator\" id=\"status-text\">සම්බන්ධතාවය ලැබුණු වහාම ස්වයංක්‍රීයව නැවත පූරණය වේ.</p>\n  </div>\n  <script>\n    window.addEventListener('online', function() {\n      document.getElementById('status-text').textContent = 'සම්බන්ධතාවය ලැබිණි! නැවත පූරණය වෙමින් පවතී...';\n      setTimeout(function() { window.location.reload(); }, 600);\n    });\n  </script>\n</body>\n</html>\n";
